import{b as e,Y as a,O as t,g as o,l as r}from"./chunks/framework.DcaUmd3X.js";const f=JSON.parse('{"title":"为什么要跑步","description":"","frontmatter":{"layout":"page","aside":false,"title":"为什么要跑步","mindmap":"# 为什么要跑步\\n## 身体\\n- 心率降低\\n  - 跑者的静息心率在50次/分钟，普通人的在72次/分钟，心率低会更长寿\\n- 排毒\\n  - 大量排汗，伴随着清洗身体毒素\\n- 摆脱身体病痛\\n  - 至少村上跑步的30年来没有什么大的病痛\\n  - 很多人说可以治三高\\n- 变瘦\\n  - 可以锻炼出匀称的肌肉\\n    - 提高基础代谢\\n  - 30分钟以上开始消解脂肪\\n\\n## 精神\\n- 减轻精神压力\\n  - 跑步流汗降压\\n- 产生快感，心情愉悦\\n  - 分泌内啡肽 多巴胺 愉悦感\\n  - 例子：跑🐎过程中受伤但跑完才发现\\n  - 每年那么多人跑🐎，如果不开心谁还做呢\\n- 变聪明\\n  - 中低强度长时间有氧运动促进海马体产生大量神经元\\n  - 不过28小时内不利用就会变成普通蛋白质\\n  - 配合知性作业可以使神经元绵密，切切实实提高大脑能力\\n\\n## 方便便宜\\n- 随时随地，只要不是下雨下雪下冰雹\\n- 便宜\\n  - 只需要一双好的跑鞋就好了\\n  - 最多加个护膝\\n\\n## 榜样\\n- 村上春树\\n  - 连续跑步30多年\\n    - 每年一次马拉松\\n    - 100公里跑之后\\n      - 跑者蓝调\\n    - 每天5~15公里\\n      - 每月300公里左右\\n  - 铁人三项运动\\n    - 跑步，游泳，自行车\\n  - 相关作品\\n    - 《当我谈跑步时，我谈些什么》\\n    - 《我的职业是小说家》\\n\\n## 注意点\\n- 跑前热身\\n  - 拉伸关节，防止损伤\\n  - 循序渐进\\n    - 不要超过身体负荷，容易运动损伤\\n    - 我们的身体就像一根弹簧\\n  - 保护膝盖\\n    - 据说每次跑步膝盖都要承受三倍身体重量\\n    - 如果有必要可以买护膝\\n  - 跑后拉伸\\n    - 放松肌肉\\n    - 顺带拉筋\\n"},"headers":[],"relativePath":"knowledge-graph/why-running/index.md","filePath":"知识图谱/6.为什么要跑步.md","lastUpdated":1782289777000}'),s={name:"knowledge-graph/why-running/index.md"};function d(p,_,i,c,l,m){const n=a("MindmapPage");return t(),o("div",null,[r(n)])}const h=e(s,[["render",d]]);export{f as __pageData,h as default};
